CREATE TABLE `technician_jobs` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `service_request_id` bigint(20) UNSIGNED NOT NULL,
  `technician_id` bigint(20) UNSIGNED NOT NULL,
  `job_type` enum('Installation','Repair') NOT NULL,
