  `scheduled_start` datetime NOT NULL,
  `scheduled_end` datetime NOT NULL,
  `status` enum('Scheduled','Assigned','In Progress','Completed','Cancelled') NOT NULL DEFAULT 'Scheduled',
  `work_performed` text DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `assigned_by` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Staff/admin user_account_id who assigned it',
  `completed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

