--
-- Structure for view `v_area_summary`
--
DROP TABLE IF EXISTS `v_area_summary`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_area_summary`  AS SELECT `a`.`id` AS `area_id`, `a`.`area_name` AS `area_name`, (select count(0) from `customers` where `customers`.`area_id` = `a`.`id`) AS `customer_count`, (select count(0) from (`subscriptions` `s` join `customers` `c` on(`c`.`id` = `s`.`customer_id`)) where `c`.`area_id` = `a`.`id` and `s`.`status` = 'Active') AS `active_subscriptions`, (select coalesce(sum(`p`.`amount`),0) from (`payments` `p` join `customers` `c` on(`c`.`id` = `p`.`customer_id`)) where `c`.`area_id` = `a`.`id`) AS `total_collected` FROM `areas` AS `a` ;

-- --------------------------------------------------------

--
-- Structure for view `v_bill_balances`
--
DROP TABLE IF EXISTS `v_bill_balances`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_bill_balances`  AS SELECT `b`.`id` AS `bill_id`, `b`.`subscription_id` AS `subscription_id`, `b`.`total_amount` AS `total_amount`, coalesce(sum(`p`.`amount`),0) AS `paid_amount`, `b`.`total_amount`- coalesce(sum(`p`.`amount`),0) AS `balance_amount`, `b`.`status` AS `status`, `b`.`due_date` AS `due_date` FROM (`bills` `b` left join `payments` `p` on(`p`.`bill_id` = `b`.`id`)) GROUP BY `b`.`id`, `b`.`subscription_id`, `b`.`total_amount`, `b`.`status`, `b`.`due_date` ;

-- --------------------------------------------------------

--
-- Structure for view `v_customer_revenue`
--
DROP TABLE IF EXISTS `v_customer_revenue`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_customer_revenue`  AS SELECT `c`.`id` AS `customer_id`, concat(`c`.`first_name`,' ',`c`.`last_name`) AS `customer_name`, `c`.`username` AS `username`, `c`.`account_status` AS `account_status`, coalesce(sum(`p`.`amount`),0) AS `total_paid`, count(`p`.`id`) AS `payment_count`, max(`p`.`payment_date`) AS `last_payment_date` FROM (`customers` `c` left join `payments` `p` on(`p`.`customer_id` = `c`.`id`)) GROUP BY `c`.`id`, `c`.`first_name`, `c`.`last_name`, `c`.`username`, `c`.`account_status` ;

-- --------------------------------------------------------

--
-- Structure for view `v_dispatch_summary`
--
DROP TABLE IF EXISTS `v_dispatch_summary`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_dispatch_summary`  AS SELECT count(0) AS `total_jobs`, coalesce(sum(case when `technician_jobs`.`status` = 'Scheduled' then 1 else 0 end),0) AS `queued`, coalesce(sum(case when `technician_jobs`.`status` = 'Assigned' then 1 else 0 end),0) AS `assigned`, coalesce(sum(case when `technician_jobs`.`status` = 'In Progress' then 1 else 0 end),0) AS `in_progress`, coalesce(sum(case when `technician_jobs`.`status` = 'Completed' then 1 else 0 end),0) AS `done`, coalesce(sum(case when `technician_jobs`.`status` = 'Cancelled' then 1 else 0 end),0) AS `cancelled` FROM `technician_jobs` ;

-- --------------------------------------------------------

--
-- Structure for view `v_expiring_subscriptions`
--
DROP TABLE IF EXISTS `v_expiring_subscriptions`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_expiring_subscriptions`  AS SELECT `s`.`id` AS `subscription_id`, `c`.`id` AS `customer_id`, concat(`c`.`first_name`,' ',`c`.`last_name`) AS `customer_name`, `c`.`username` AS `username`, `p`.`plan_name` AS `plan_name`, `s`.`end_date` AS `end_date`, to_days(`s`.`end_date`) - to_days(curdate()) AS `days_left` FROM ((`subscriptions` `s` join `customers` `c` on(`c`.`id` = `s`.`customer_id`)) join `internet_plans` `p` on(`p`.`id` = `s`.`plan_id`)) WHERE `s`.`status` = 'Active' AND `s`.`end_date` is not null AND `s`.`end_date` between curdate() and curdate() + interval 30 day ;

-- --------------------------------------------------------

--
-- Structure for view `v_inventory_stock`
--
DROP TABLE IF EXISTS `v_inventory_stock`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_inventory_stock`  AS SELECT `i`.`id` AS `item_id`, `i`.`item_name` AS `item_name`, `i`.`category` AS `category`, `i`.`unit` AS `unit`, `i`.`reorder_level` AS `reorder_level`, coalesce(sum(case when `m`.`movement_type` = 'IN' then `m`.`quantity` when `m`.`movement_type` = 'OUT' then -`m`.`quantity` else 0 end),0) AS `current_stock` FROM (`inventory_items` `i` left join `inventory_movements` `m` on(`m`.`item_id` = `i`.`id`)) GROUP BY `i`.`id`, `i`.`item_name`, `i`.`category`, `i`.`unit`, `i`.`reorder_level` ;

-- --------------------------------------------------------

--
-- Structure for view `v_monthly_collections`
--
DROP TABLE IF EXISTS `v_monthly_collections`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_monthly_collections`  AS SELECT date_format(`payments`.`payment_date`,'%Y-%m') AS `month`, coalesce(sum(`payments`.`amount`),0) AS `total_collected`, count(0) AS `payment_count` FROM `payments` GROUP BY date_format(`payments`.`payment_date`,'%Y-%m') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure for view `v_node_port_summary`
--
DROP TABLE IF EXISTS `v_node_port_summary`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_node_port_summary`  AS SELECT `n`.`id` AS `node_id`, `n`.`node_code` AS `node_code`, `n`.`node_type` AS `node_type`, `n`.`port_capacity` AS `port_capacity`, (select count(0) from `network_ports` where `network_ports`.`node_id` = `n`.`id` and `network_ports`.`port_status` = 'Active') AS `active_ports`, (select count(0) from `network_ports` where `network_ports`.`node_id` = `n`.`id` and `network_ports`.`port_status` = 'Reserved') AS `reserved_ports`, (select count(0) from `network_ports` where `network_ports`.`node_id` = `n`.`id` and `network_ports`.`port_status` = 'Available') AS `available_ports`, (select count(0) from `network_ports` where `network_ports`.`node_id` = `n`.`id` and `network_ports`.`port_status` = 'Faulty') AS `faulty_ports` FROM `network_nodes` AS `n` ;

-- --------------------------------------------------------

--
-- Structure for view `v_popular_plans`
--
DROP TABLE IF EXISTS `v_popular_plans`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_popular_plans`  AS SELECT `p`.`id` AS `plan_id`, `p`.`plan_name` AS `plan_name`, `p`.`monthly_price` AS `monthly_price`, count(`s`.`id`) AS `active_subscriptions` FROM (`internet_plans` `p` left join `subscriptions` `s` on(`s`.`plan_id` = `p`.`id` and `s`.`status` = 'Active')) GROUP BY `p`.`id`, `p`.`plan_name`, `p`.`monthly_price` ;

-- --------------------------------------------------------

--
-- Structure for view `v_technician_workload`
--
DROP TABLE IF EXISTS `v_technician_workload`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_technician_workload`  AS SELECT `t`.`id` AS `technician_id`, concat(`t`.`first_name`,' ',`t`.`last_name`) AS `technician_name`, `t`.`availability` AS `availability`, coalesce(sum(case when `j`.`status` in ('Scheduled','Assigned','In Progress') then 1 else 0 end),0) AS `active_jobs`, coalesce(sum(case when `j`.`status` = 'Completed' then 1 else 0 end),0) AS `completed_jobs` FROM (`technicians` `t` left join `technician_jobs` `j` on(`j`.`technician_id` = `t`.`id`)) GROUP BY `t`.`id`, `t`.`first_name`, `t`.`last_name`, `t`.`availability` ;

